package com.logatron.processor.protect;
import com.logatron.processor.configuration.IngestionProperties;import org.springframework.stereotype.Component;import java.util.*;import java.util.regex.*;
@Component public class SensitiveDataMasker {private final String replacement;private final boolean enabled;private final List<Rule> rules;public SensitiveDataMasker(IngestionProperties p){enabled=p.masking().enabled();replacement=p.masking().replacement();rules=List.of(new Rule(Pattern.compile("(?i)(authorization\\s*[:=]\\s*bearer\\s+)[^\\s,;\\\"]+"),"$1"+replacement),new Rule(Pattern.compile("(?i)((?:password|passwd|api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|credential|secret)\\s*[:=]\\s*[\\\"]?)[^\\s,;&\\\"]+"),"$1"+replacement),new Rule(Pattern.compile("(?i)([?&](?:password|passwd|api[_-]?key|token|secret)=)[^&#\\s]+"),"$1"+replacement),new Rule(Pattern.compile("(?i)(jdbc:[a-z0-9]+://[^:/@\\s]+:)[^@/\\s]+(@)"),"$1"+replacement+"$2"),new Rule(Pattern.compile("\\beyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\b"),replacement));}public String mask(String input){if(!enabled||input==null)return input;String result=input;for(Rule r:rules)result=r.pattern.matcher(result).replaceAll(Matcher.quoteReplacement(r.replacement).replace("\\$","$"));return result;}public Map<String,String> mask(Map<String,String> values){if(values==null)return Map.of();Map<String,String> out=new LinkedHashMap<>();values.forEach((k,v)->out.put(k,mask(v)));return out;}private record Rule(Pattern pattern,String replacement){}
}